const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const grafton = ee.Geometry.Point([152.933, -29.681]); // Grafton, NSW
  const region = grafton.buffer(5000); // 5km buffer around Grafton
  const startDate = '2020-01-14';
  const endDate = '2020-01-22';

  // 2. Data Acquisition - CHIRPS daily precipitation
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(region);

  const collectionSize = chirps.size().getInfo();
  console.log(`CHIRPS images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over the period
  const totalPrecip = chirps.sum();

  // Get pixel count and total precipitation
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count().combine({
      reducer2: ee.Reducer.sum(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  });

  const pixelCount = stats.get('precipitation_count').getInfo();
  const totalRainfall = stats.get('precipitation_sum').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);
  console.log(`Total rainfall (mm): ${totalRainfall ? totalRainfall.toFixed(1) : 'null'}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (totalRainfall === null || totalRainfall === undefined || isNaN(totalRainfall)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const rainfallInches = totalRainfall / 25.4;
  console.log(`Total rainfall (inches): ${rainfallInches.toFixed(2)}`);
  console.log(`Threshold: 6 inches`);

  // 4. Final Answer
  if (rainfallInches > 6) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
